begin;\n\n-- ADT Stock V284: audit reset compare-and-swap.\n-- Prevents a member who has not yet received a manager reset from writing the old audit\n-- back to the team cloud after the reset.\n\ncreate or replace function public.adt_cloud_state_set_pair_v284(\n  p_team_id text,\n  p_user_id text,\n  p_state_key text,\n  p_state_value jsonb,\n  p_meta_value jsonb,\n  p_expected_updated_at bigint default null\n)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path=public,pg_temp\nas $$\ndeclare\n  v_meta_key text := p_state_key || '__adt_meta_v273';\n  v_current_meta jsonb;\n  v_current_updated bigint := 0;\nbegin\n  if p_state_value is null or p_meta_value is null then raise exception 'INVALID_STATE'; end if;\n  if not public.adt_cloud_state_allowed(p_team_id,p_user_id,p_state_key,true)\n     or not public.adt_cloud_state_allowed(p_team_id,p_user_id,v_meta_key,true) then\n    raise exception 'NOT_ALLOWED';\n  end if;\n\n  select state_value into v_current_meta\n  from public.adt_team_cloud_state\n  where team_id=p_team_id::uuid and state_key=v_meta_key\n  for update;\n\n  v_current_updated := coalesce(nullif((v_current_meta->>'updatedAt'),'')::bigint,0);\n\n  if p_expected_updated_at is not null and v_current_updated > p_expected_updated_at then\n    return false;\n  end if;\n\n  insert into public.adt_team_cloud_state(team_id,state_key,state_value,updated_by)\n  values(p_team_id::uuid,p_state_key,p_state_value,p_user_id)\n  on conflict(team_id,state_key) do update\n    set state_value=excluded.state_value,updated_by=excluded.updated_by,updated_at=now();\n\n  insert into public.adt_team_cloud_state(team_id,state_key,state_value,updated_by)\n  values(p_team_id::uuid,v_meta_key,p_meta_value,p_user_id)\n  on conflict(team_id,state_key) do update\n    set state_value=excluded.state_value,updated_by=excluded.updated_by,updated_at=now();\n\n  return true;\nend;\n$$;\n\nrevoke all on function public.adt_cloud_state_set_pair_v284(text,text,text,jsonb,jsonb,bigint) from public;\ngrant execute on function public.adt_cloud_state_set_pair_v284(text,text,text,jsonb,jsonb,bigint) to anon,authenticated;\n\ncommit;\n\nnotify pgrst,'reload schema';\nselect 'ADT Stock V284 audit reset CAS installed' as result;\n